package dev.smpcristalix.pvpcombat.service;
import dev.smpcristalix.pvpcombat.config.PvPCombatSettings;import org.bukkit.entity.Player;import java.util.*;
/** Эфемерное состояние текущего PvP-боя. */
public final class CombatService{private final Map<UUID,State> states=new HashMap<>();private PvPCombatSettings settings;public CombatService(PvPCombatSettings s){settings=s;}public void reload(PvPCombatSettings s){settings=s;}public void tag(Player a,Player b){long now=System.currentTimeMillis(),exp=now+settings.combatDurationSeconds()*1000L;states.compute(a.getUniqueId(),(id,o)->update(o,b.getUniqueId(),now,exp));states.compute(b.getUniqueId(),(id,o)->update(o,a.getUniqueId(),now,exp));}private State update(State o,UUID opp,long now,long exp){if(o==null||o.expiresAt<now)return new State(opp,now,exp);o.opponent=opp;o.expiresAt=exp;return o;}public boolean inCombat(Player p){return remainingMillis(p)>0;}public long remainingMillis(Player p){State s=states.get(p.getUniqueId());return s==null?0:Math.max(0,s.expiresAt-System.currentTimeMillis());}public long fightDurationMillis(Player p){State s=states.get(p.getUniqueId());return s==null?0:Math.max(0,System.currentTimeMillis()-s.startedAt);}public UUID opponent(Player p){State s=states.get(p.getUniqueId());return s==null?null:s.opponent;}public void clear(Player p){states.remove(p.getUniqueId());}public void clearExpired(){states.entrySet().removeIf(e->e.getValue().expiresAt<=System.currentTimeMillis());}private static final class State{private UUID opponent;private final long startedAt;private long expiresAt;State(UUID o,long s,long e){opponent=o;startedAt=s;expiresAt=e;}}}
